#!/usr/bin/env bash

set -euo pipefail

REPO="ktul15/multi-vendor-e-commerce-app"

ensure_label() {
  gh label create "$1" --repo "$REPO" --color "$2" --description "$3" --force >/dev/null
}

ensure_milestone() {
  local title="$1"
  local description="$2"
  if ! gh api "repos/$REPO/milestones?state=all&per_page=100" --jq ".[] | select(.title == \"$title\") | .title" | grep -Fxq "$title"; then
    gh api "repos/$REPO/milestones" -f title="$title" -f description="$description" >/dev/null
  fi
}

create_issue() {
  local title="$1"
  local labels="$2"
  local milestone="$3"
  local body="$4"
  local existing
  existing="$(gh issue list --repo "$REPO" --state all --limit 200 --search "$title in:title" --json title --jq ".[] | select(.title == \"$title\") | .title")"
  if [[ "$existing" == "$title" ]]; then
    echo "skip: $title"
    return
  fi
  gh issue create --repo "$REPO" --title "$title" --label "$labels" --milestone "$milestone" --body "$body"
}

ensure_label "web-migration" "1D76DB" "Migration of Flutter dashboards to Next.js"
ensure_label "shared-web" "5319E7" "Shared web workspace, UI, schemas, and API client"
ensure_label "security" "B60205" "Authentication, authorization, and application security"
ensure_label "accessibility" "0E8A16" "Accessibility and keyboard interaction"
ensure_label "observability" "006B75" "Logging, monitoring, analytics, and diagnostics"
ensure_label "vendor-dash" "F9D0C4" "Vendor dashboard work"
